#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <queue>
#include <span>
#include <string>
#include <utility>
#include <vector>

struct WeightedEdge {
  std::ptrdiff_t from = 0;
  std::ptrdiff_t to = 0;
  std::int64_t weight = 0;
};

struct Visit {
  std::ptrdiff_t station = 0;
  std::int64_t distance = 0;
};

// priority_queue calls this "less": comp(a, b) true means a leaves the heap after b. The nearest
// station has to leave first, so the one with the larger distance is the one that leaves after.
struct FartherOut {
  bool operator()(const Visit& a, const Visit& b) const { return a.distance > b.distance; }
};

[[nodiscard]] std::vector<std::optional<std::int64_t>> shortest_distances(std::ptrdiff_t n,
                                                                           std::span<const WeightedEdge> edges,
                                                                           std::ptrdiff_t start) {
  std::vector<std::vector<std::pair<std::ptrdiff_t, std::int64_t>>> neighbours(static_cast<std::size_t>(n));
  for (const WeightedEdge& e : edges) {
    neighbours[static_cast<std::size_t>(e.from)].push_back({e.to, e.weight});
    neighbours[static_cast<std::size_t>(e.to)].push_back({e.from, e.weight});
  }
  std::vector<std::optional<std::int64_t>> best(static_cast<std::size_t>(n));
  std::priority_queue<Visit, std::vector<Visit>, FartherOut> frontier;
  best[static_cast<std::size_t>(start)] = 0;
  frontier.push({.station = start, .distance = 0});
  while (!frontier.empty()) {
    const Visit current = frontier.top();
    frontier.pop();
    const auto& settled = best[static_cast<std::size_t>(current.station)];
    if (settled && *settled < current.distance) continue;  // a shorter route already settled this station
    for (const auto& [neighbour, weight] : neighbours[static_cast<std::size_t>(current.station)]) {
      const std::int64_t candidate = current.distance + weight;
      auto& known = best[static_cast<std::size_t>(neighbour)];
      if (!known || candidate < *known) {
        known = candidate;
        frontier.push({.station = neighbour, .distance = candidate});
      }
    }
  }
  return best;
}

[[nodiscard]] std::string show(const std::optional<std::int64_t>& d) {
  return d ? std::format("{}", *d) : "no value";
}

int main() {
  const std::vector<WeightedEdge> edges{
      {.from = 0, .to = 1, .weight = 4}, {.from = 0, .to = 2, .weight = 1}, {.from = 2, .to = 1, .weight = 2},
      {.from = 1, .to = 3, .weight = 1}, {.from = 2, .to = 3, .weight = 5}, {.from = 3, .to = 4, .weight = 3},
  };
  const std::vector<std::optional<std::int64_t>> distances = shortest_distances(6, edges, 0);
  for (std::size_t i = 0; i < distances.size(); ++i) std::cout << std::format("{}: {}\n", i, show(distances[i]));
}

#include <array>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <string>
#include <string_view>

[[nodiscard]] std::optional<std::string_view> shortest_covering_window(std::string_view text,
                                                                        std::string_view pattern) {
  std::array<std::int64_t, 256> need{};
  for (const char c : pattern) ++need[static_cast<unsigned char>(c)];
  std::int64_t missing = std::ssize(pattern);  // bytes still short of pattern's required count
  std::array<std::int64_t, 256> have{};
  std::ptrdiff_t left = 0;
  std::ptrdiff_t best_start = 0;
  std::ptrdiff_t best_len = -1;  // -1 means no covering window found yet
  for (std::ptrdiff_t right = 0; right < std::ssize(text); ++right) {
    const auto c = static_cast<unsigned char>(text[right]);
    if (have[c] < need[c]) --missing;  // this occurrence is still needed
    ++have[c];
    while (missing == 0) {
      if (best_len == -1 || right - left + 1 < best_len) {
        best_len = right - left + 1;
        best_start = left;
      }
      const auto lc = static_cast<unsigned char>(text[left]);
      --have[lc];
      if (have[lc] < need[lc]) ++missing;
      ++left;
    }
  }
  if (best_len == -1) return std::nullopt;
  return text.substr(static_cast<std::size_t>(best_start), static_cast<std::size_t>(best_len));
}

[[nodiscard]] std::string show(const std::optional<std::string_view>& window) {
  return window ? std::format("\"{}\"", *window) : "no value";
}

int main() {
  std::cout << show(shortest_covering_window("ADOBECODEBANC", "ABC")) << '\n';
  std::cout << show(shortest_covering_window("a", "a")) << '\n';
  std::cout << show(shortest_covering_window("a", "aa")) << '\n';
  std::cout << show(shortest_covering_window("aa", "a")) << '\n';
  std::cout << show(shortest_covering_window("", "a")) << '\n';
}
